`,e.jsx(n,{type:"warn",title:"Backend migration steps are provisional",children:e.jsx(i.p,{children:"The 4.0.0 release is upcoming and the backend migration steps on this page are provisional. Verify each procedure against the final release artifacts before upgrading production."})}),`
`,e.jsx(i.h2,{id:"architecture-changes",children:"Architecture changes"}),`
`,e.jsx(i.h3,{id:"one-postgresql-database-with-schemas",children:"One PostgreSQL database with schemas"}),`
`,e.jsxs(i.p,{children:["3.8.0 gave each service its own database. The 4.0.0 backend connects to a single PostgreSQL database named ",e.jsx(i.code,{children:"pki"})," and isolates each service in a schema: ",e.jsx(i.code,{children:"kms"}),", ",e.jsx(i.code,{children:"ca"}),", ",e.jsx(i.code,{children:"va"}),", ",e.jsx(i.code,{children:"devicemanager"}),", ",e.jsx(i.code,{children:"dmsmanager"})," and ",e.jsx(i.code,{children:"alerts"}),". The ",e.jsx(i.code,{children:"authz"})," service keeps its principals, grants and policies in a separate ",e.jsx(i.code,{children:"authz"})," database (the development monolith uses an ",e.jsx(i.code,{children:"authz"})," schema inside ",e.jsx(i.code,{children:"pki"})," instead), and WFX keeps its own ",e.jsx(i.code,{children:"wfx"})," database."]}),`
`,e.jsxs(i.p,{children:["PostgreSQL is now the only storage engine. SQLite support is removed, and the ",e.jsx(i.code,{children:"couch_db"})," and ",e.jsx(i.code,{children:"dynamo_db"})," engines are not registered in 4.0.0."]}),`
`,e.jsx(i.h3,{id:"authorization-moves-into-the-authz-service",children:"Authorization moves into the authz service"}),`
`,e.jsx(i.p,{children:"In 3.8.0 the API Gateway validated tokens: a JWT policy on every private route checked the signature and only let through tokens that carried the administrator role. Every route was open to any token that passed that check."}),`
`,e.jsxs(i.p,{children:["4.0.0 removes the gateway policy. The ",e.jsx(i.code,{children:"/api/*"})," routes reach the services directly, and each service authorizes every request through ",e.jsx(i.code,{children:"authz"}),", which validates the token against the identity provider's JWKS endpoint and applies fine-grained, entity-level policies to CAs, certificates, devices, DMSs, KMS keys and VA roles. There is no implicit superuser: the first administrator comes from a bootstrap principal that you configure. The ",e.jsx(i.a,{href:"/docs/platform/administration/access-control",children:"access control"})," page documents principals, policies and the first administrator."]}),`
`,e.jsx(i.h3,{id:"device-events-get-their-own-store",children:"Device events get their own store"}),`
`,e.jsxs(i.p,{children:["Historical device events move from the ",e.jsx(i.code,{children:"devices.events"})," column to a dedicated ",e.jsx(i.code,{children:"device_events"})," store with their own endpoints. The events endpoint can also stream events over Server-Sent Events (SSE); to fan events out across service instances, each Device Manager instance binds its own durable AMQP queue."]}),`
`,e.jsx(i.h3,{id:"a-hardened-helm-chart",children:"A hardened Helm chart"}),`
`,e.jsx(i.p,{children:"Version 4.0.0 of the chart is a security-hardening release:"}),`
`,e.jsxs(i.ul,{children:[`
`,e.jsxs(i.li,{children:[e.jsx(i.strong,{children:"Release-scoped resource names."})," Every chart-managed resource is named ",e.jsx(i.code,{children:"<release>-lamassu-<component>"})," instead of the fixed names used in 3.8.0 (",e.jsx(i.code,{children:"kms"}),", ",e.jsx(i.code,{children:"va"}),", ",e.jsx(i.code,{children:"ca"}),", ...). With a release named ",e.jsx(i.code,{children:"prod"})," the StatefulSets become ",e.jsx(i.code,{children:"prod-lamassu-kms"})," and ",e.jsx(i.code,{children:"prod-lamassu-va"}),". The ",e.jsx(i.code,{children:"nameOverride"})," and ",e.jsx(i.code,{children:"fullnameOverride"})," values change the prefix."]}),`
`,e.jsxs(i.li,{children:[e.jsx(i.strong,{children:"Non-root containers."})," Every workload runs as the numeric user ",e.jsx(i.code,{children:"65532:65532"})," with a ",e.jsx(i.code,{children:"RuntimeDefault"})," seccomp profile and dropped capabilities. Pods do not mount the service-account token by default, and the chart creates a dedicated ServiceAccount."]}),`
`,e.jsxs(i.li,{children:[e.jsx(i.strong,{children:"Strict values validation."})," ",e.jsx(i.code,{children:"values.schema.json"})," rejects unknown keys, so leftover 3.8.0 blocks fail ",e.jsx(i.code,{children:"helm lint"})," and ",e.jsx(i.code,{children:"helm upgrade"})," instead of being silently ignored."]}),`
`,e.jsxs(i.li,{children:[e.jsx(i.strong,{children:"No injected scheduling rules."})," The chart no longer adds pod anti-affinity or topology spread constraints on its own."]}),`
`]}),`
`,e.jsx(i.h3,{id:"what-the-upgrade-migrates-automatically",children:"What the upgrade migrates automatically"}),`
`,e.jsx(i.p,{children:"Several migrations run without intervention when you upgrade a Helm release:"}),`
`,e.jsxs(i.ul,{children:[`
`,e.jsxs(i.li,{children:["Before any service starts, the chart's pre-install/pre-upgrade job prepares PostgreSQL. It creates the ",e.jsx(i.code,{children:"pki"}),", ",e.jsx(i.code,{children:"authz"})," and ",e.jsx(i.code,{children:"wfx"})," databases when they do not exist, creates one schema per service inside ",e.jsx(i.code,{children:"pki"}),", and imports each 3.8.0 per-service database into its schema. Each import runs as a single transaction, so a failed import leaves no partial schema and a retried job imports again. The job then runs the database migrations for every schema, migrates ",e.jsx(i.code,{children:"authz"}),", preloads its policies and seeds the ",e.jsx(i.code,{children:"services.authz.bootstrap"})," principals. It is idempotent and requires a PostgreSQL role allowed to create databases and schemas, as described in ",e.jsx(i.a,{href:"/docs/deployment/self-hosted/helm#before-you-begin",children:"Install with Helm"}),"."]}),`
`,e.jsx(i.li,{children:"Stored DMS configuration is rewritten to the 4.0.0 layout, and historical device events are transformed into the new store."}),`
`,e.jsxs(i.li,{children:["When ",e.jsx(i.code,{children:"migrations.caToKms.enabled"})," is set, a pre-upgrade hook registers legacy CA keys in the KMS."]}),`
`]}),`
`,e.jsxs(i.p,{children:["Two things never migrate on their own: the KMS and VA data on local volumes, which stays on volumes the upgraded pods no longer use, and the values file, which you update by hand. Deployments that do not use the Helm chart also have to move their database data themselves; see ",e.jsx(i.a,{href:"#deployments-without-helm",children:"Deployments without Helm"}),"."]}),`
